const taipeiDayFormatter=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'});
// Display-only identity hiding: raw downloaded data and backup remain intact.
export function identityVisible(s,state={}){return !s.blind||s.blind.revealed===true||state.finished===true;}
export function relativeDay(s,value){const raw=String(value??''),date=raw.includes('T')&&Number.isFinite(Date.parse(raw))?taipeiDayFormatter.format(new Date(raw)):raw.slice(0,10),bars=[...(s.history??[]),...s.rounds.map(r=>r.bar).filter(Boolean)],start=(s.history??[]).length;let i=bars.findIndex(b=>b.date===date);if(i>=0)return i<start?`練習前 ${start-i} 日`:`第 ${i-start+1} 交易日`;if(date<(bars[0]?.date??s.startDate))return '練習前的更早資料';i=bars.findLastIndex(b=>b.date<=date);return i<start?`練習前 ${start-i} 日之後`:`第 ${i-start+1} 交易日後`;}
export function blindText(value,s){return String(value??'').replaceAll(String(s.asset??'0050 元大台灣50'),'標的 A').replace(/0050(?:\.TW)?|元大台灣\s*50|元大台灣五十|元大臺灣\s*50/gi,'標的 A').replace(/https?:\/\/\S+/gi,'[原始連結待揭露]').replace(/民國\s*\d{2,3}\s*年(?:\s*\d{1,2}\s*月(?:\s*\d{1,2}\s*日)?)?/g,'[日期隱藏]').replace(/\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+(?:19|20)\d{2}\b/gi,'[日期隱藏]').replace(/\b(?:JANUARY|FEBRUARY|MARCH|APRIL|MAY|JUNE|JULY|AUGUST|SEPTEMBER|OCTOBER|NOVEMBER|DECEMBER)\s+\d{4}\b/gi,'該統計月份').replace(/\b(?:19|20)\d{2}[-/.年]\d{1,2}(?:[-/.月]\d{1,2}日?)?/g,'[日期隱藏]').replace(/\b(?:19|20)\d{2}\s*年/g,'該年').replace(/\d{1,2}\s*月\s*\d{1,2}\s*日/g,'該日').replace(/(?<![\d.])(?:1[0-2]|0?[1-9])\s*月(?:份)?/g,'該月').replace(/\b(?:January|February|March|April|June|July|August|September|October|November|December)\b/gi,'該月').replace(/\b(?:May|MAY)\b/g,'該月').replace(/\b(in|during|since|until|by|of)\s+may\b/g,'$1 該月');}
export function newsView(s,state,n){if(identityVisible(s,state))return n;return {title:blindText(n.blindTitle??n.title,s),body:blindText(n.blindBody??n.body,s),source:'公告與新聞精選（原始連結於揭露後提供）',availableAt:relativeDay(s,n.availableAt??n.publishedAt),publishedAt:relativeDay(s,n.publishedAt??n.availableAt),vintageNote:blindText(n.vintageNote,s),vintageCaveats:n.vintageCaveats?.length?['註記']:[],timestampPrecision:n.timestampPrecision};}
